'use strict';
const $=id=>document.getElementById(id);
const STORAGE='ee-calendar.v2.';
function read(key,fallback){try{const value=JSON.parse(localStorage.getItem(STORAGE+key));return value??fallback}catch{return fallback}}
function persist(key,value){try{localStorage.setItem(STORAGE+key,JSON.stringify(value))}catch{toast('Browser storage is unavailable. Changes last for this visit only.')}}
let customCourses=read('customCourses',[]);if(!Array.isArray(customCourses))customCourses=[];
let courses=[...courseCatalog,...customCourses.filter(c=>c&&typeof c.id==='string'&&typeof c.name==='string'&&[0,1,2,3].includes(c.sectionCount)&&['A','B','AB'].includes(c.term)&&!courseCatalog.some(k=>k.id===c.id))];
let selectedRoute=read('route','base');if(!routeCatalog[selectedRoute])selectedRoute='base';
let manualAdds=read('manualAdds',[]),manualRemoves=read('manualRemoves',[]);if(!Array.isArray(manualAdds))manualAdds=[];if(!Array.isArray(manualRemoves))manualRemoves=[];
const isWriting=id=>['WRIT 2130F','WRIT 2130G','WRIT 2130F/G'].includes(id);
const migrateWriting=id=>id==='WRIT 2130F/G'?'WRIT 2130G':id;
manualAdds=manualAdds.map(migrateWriting);manualRemoves=manualRemoves.map(migrateWriting);

let prefs=read('prefs',{});if(!prefs||typeof prefs!=='object'||Array.isArray(prefs))prefs={};
if(prefs['WRIT 2130F/G']&&!prefs['WRIT 2130G'])prefs['WRIT 2130G']={...prefs['WRIT 2130F/G']};
courses.forEach(c=>{if(!prefs[c.id]||typeof prefs[c.id].enabled!=='boolean')prefs[c.id]={enabled:true,section:c.sectionCount===0?'none':''}});
// Migrate the former semester selector once; then each Writing checkbox is independent.
if(!read('writingCheckboxes',false)){
  const previousTerm=read('writingTerm',null);
  const enabledTerm=['F','G'].includes(previousTerm)?previousTerm:(selectedRoute==='aise'?'G':'F');
  prefs['WRIT 2130F'].enabled=enabledTerm==='F';
  prefs['WRIT 2130G'].enabled=enabledTerm==='G';
  persist('prefs',prefs);persist('writingCheckboxes',true);
}
function activeCourses(){const ids=new Set([...routeCatalog[selectedRoute].courses,...manualAdds]);if([...ids].some(isWriting)){ids.add('WRIT 2130F');ids.add('WRIT 2130G')}return courses.filter(c=>ids.has(c.id)&&!manualRemoves.includes(c.id))}
function sectionOptions(c){return c.sectionCount===0?[]:Array.from({length:c.sectionCount??3},(_,i)=>String(i+1).padStart(3,'0'))}
const seed=[['Problem set 04','ECE 2205A','Assignment','2026-11-16','23:59','all'],['Digital logic quiz','ECE 2277A','Quiz','2026-11-17','09:30','001'],['Digital logic quiz','ECE 2277A','Quiz','2026-11-18','14:30','002'],['Electrical laboratory report','ECE 2240A','Lab','2026-11-19','17:00','all'],['Applied mathematics assignment','NMM 2270A','Assignment','2026-11-20','23:59','all'],['Electric circuits term test','ECE 2205A','Test','2026-11-23','18:00','all'],['Programming assignment','CS 1027A','Assignment','2026-11-25','23:59','all'],['Algorithms assignment','AISE 2205A','Assignment','2026-11-25','23:59','all'],['Biomedical design review','BME 3201A','Assignment','2026-11-26','12:00','all'],['Accounting case','BUS 2257','Assignment','2026-11-27','17:00','all'],['Circuits and systems assignment','ECE 2233B','Assignment','2027-01-20','23:59','all']].map((e,i)=>({id:'route-sample-'+i,title:e[0],course:e[1],type:e[2],date:e[3],time:e[4],section:e[5],status:'Confirmed',notes:'Example deadline only. The course is from a progression sheet, but this date and any section numbers are fictional.',source:''}));
let events=read('events',seed);if(Array.isArray(events))events=events.map(e=>e&&({...e,course:migrateWriting(e.course)}));if(!Array.isArray(events)||!events.every(e=>e&&courses.some(c=>c.id===e.course)&&/^\d{4}-\d{2}-\d{2}$/.test(e.date)))events=seed;
let view='list',admin=false,month=new Date(2026,10,1);const nowKey=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const course=id=>courses.find(c=>c.id===id);const date=s=>new Date(s+'T12:00:00');const fmt=(s,opts)=>date(s).toLocaleDateString('en-CA',opts);const monthKey=()=>`${month.getFullYear()}-${String(month.getMonth()+1).padStart(2,'0')}`;const time=t=>{if(!t)return 'Time TBA';const[h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'p.m.':'a.m.'}`};
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',3300)}
function filtered(){const active=new Set(activeCourses().map(c=>c.id));return events.filter(e=>admin||(active.has(e.course)&&prefs[e.course].enabled&&(e.section==='all'||e.section===prefs[e.course].section))).filter(e=>(!$('typeFilter').value||e.type===$('typeFilter').value)&&(`${e.title} ${e.course} ${course(e.course).name}`).toLowerCase().includes($('search').value.toLowerCase())).sort((a,b)=>(a.date+(a.time||'')).localeCompare(b.date+(b.time||'')))}
function setCourseEnabled(id,enabled){prefs[id].enabled=enabled;persist('prefs',prefs);render();if($('coursesDialog').open)renderCatalog()}
function renderCourses(){const active=activeCourses();$('courseFilters').innerHTML=active.map(c=>`<div class="course-item" style="--course:${c.color}"><label class="course-filter"><input type="checkbox" data-course="${escape(c.id)}" aria-label="Show ${escape(c.id)}" ${prefs[c.id].enabled?'checked':''}><span class="dot"></span><span>${escape(c.id)}${isWriting(c.id)?`<em class="writing-semester">Semester ${c.term==='A'?'1':'2'}</em>`:''}</span><small>${prefs[c.id].section==='none'?'':escape(prefs[c.id].section||'—')}</small></label><button class="remove-course" data-remove-course="${escape(c.id)}" aria-label="Remove ${escape(c.id)}" title="Remove ${escape(c.id)} from my courses">×</button></div>`).join('')||'<p class="fine">Use + to add courses.</p>';document.querySelectorAll('[data-course]').forEach(el=>el.onchange=()=>setCourseEnabled(el.dataset.course,el.checked));document.querySelectorAll('[data-remove-course]').forEach(el=>el.onclick=()=>removeCourse(el.dataset.removeCourse));$('routeLabel').textContent=routeCatalog[selectedRoute].label;$('routeNote').textContent=routeCatalog[selectedRoute].note;['aise','bme','ivey'].forEach(r=>$('route-'+r).checked=selectedRoute===r)}
function eventButton(e,calendar=false){const c=course(e.course);return calendar?`<button class="calendar-event" style="--course:${c.color}" data-event="${escape(e.id)}"><small>${escape(e.course)} · ${escape(e.type)}</small>${escape(e.title)}</button>`:`<div class="event-row" role="button" tabindex="0" data-event="${escape(e.id)}" aria-label="${escape(e.title)}" style="--course:${c.color}"><span class="event-symbol">${({Assignment:'▤',Quiz:'✧',Lab:'⌁',Test:'◷',Exam:'▦'})[e.type]||'▤'}</span><div><div class="event-title">${escape(e.title)}</div><div class="event-meta"><span class="dot"></span><span>${escape(c.id)}</span><span>·</span><span>${e.section==='all'?(c.sectionCount===0?'No sections':'All sections'):escape(e.section)}</span>${e.status==='Tentative'?'<span>· Tentative</span>':''}</div></div><span class="badge ${escape(e.type)}">${escape(e.type)}</span><div class="event-time">${time(e.time)}<small>${e.type==='Assignment'||e.type==='Lab'?'Due time':'Starts at'}</small></div><span class="arrow">${admin?'✎':'↗'}</span></div>`}
function render(){renderCourses();const all=filtered(),visible=all.filter(e=>e.date.startsWith(monthKey()));const upcoming=all.filter(e=>e.date>=nowKey);const start=date(nowKey),end=new Date(start);end.setDate(end.getDate()+7);const week=upcoming.filter(e=>date(e.date)<end);$('stats').innerHTML=[['Due in the next 7 days',week.length,'For your selected sections','◷'],['On your calendar',visible.length,month.toLocaleDateString('en-CA',{month:'long',year:'numeric'}),'▦'],['Your courses',activeCourses().filter(c=>prefs[c.id].enabled).length,'Courses selected','▤']].map(s=>`<div class="stat"><span class="stat-label">${s[0]}</span><span class="stat-icon">${s[3]}</span><div class="stat-value">${s[1]}</div><div class="stat-note">${s[2]}</div></div>`).join('');$('monthLabel').textContent=month.toLocaleDateString('en-CA',{month:'long',year:'numeric'});$('eventCount').textContent=`${visible.length} event${visible.length===1?'':'s'}`;$('listView').classList.toggle('selected',view==='list');$('calendarView').classList.toggle('selected',view==='calendar');$('addEvent').hidden=!admin;$('pageLabel').textContent=admin?'Admin workspace':'My schedule';$('title').innerHTML=admin?'Manage events':'Course schedule';$('subtitle').textContent=admin?'Manage sample deadlines. Changes are saved in this browser only.':'Assignments, quizzes and exams for your selected sections.';$('scheduleNav').classList.toggle('active',!admin);$('adminNav').classList.toggle('active',admin);const missing=activeCourses().filter(c=>prefs[c.id].enabled&&!prefs[c.id].section&&events.some(e=>e.course===c.id&&e.section!=='all'));let html=admin?'<div class="admin-note">Demo admin workspace · Showing all courses and sections. Click an event to edit it. Shared publishing and secure admin accounts are not connected yet.</div>':'';
if(!admin&&missing.length)html+=`<div class="section-reminder">Choose your section for ${missing.map(c=>escape(c.id)).join(', ')} to include section-specific dates. <button id="chooseMissingSections">Choose sections</button></div>`;if(view==='list'){let last='';visible.forEach(e=>{if(last!==e.date){last=e.date;html+=`<div class="day-heading"><b>${fmt(e.date,{weekday:'long'}).toUpperCase()}</b> &nbsp; ${fmt(e.date,{month:'long',day:'numeric'}).toUpperCase()}${e.date===nowKey?' &nbsp; · TODAY':''}</div>`}html+=eventButton(e)});if(!visible.length)html+='<div class="empty">No events this month.<br><br>Try another month, course, or filter.</div>'}else{html+='<div class="calendar">'+['SUN','MON','TUE','WED','THU','FRI','SAT'].map(d=>`<div class="weekday">${d}</div>`).join('');const first=new Date(month.getFullYear(),month.getMonth(),1),start=new Date(first);start.setDate(1-first.getDay());const days=Math.ceil((first.getDay()+new Date(month.getFullYear(),month.getMonth()+1,0).getDate())/7)*7;for(let i=0;i<days;i++){const d=new Date(start);d.setDate(start.getDate()+i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;html+=`<div class="calendar-day ${d.getMonth()!==month.getMonth()?'outside':''} ${key===nowKey?'is-today':''}"><span class="day-number">${d.getDate()}</span>${all.filter(e=>e.date===key).map(e=>eventButton(e,true)).join('')}</div>`}html+='</div>'}$('events').innerHTML=html;if($('chooseMissingSections'))$('chooseMissingSections').onclick=openSections;document.querySelectorAll('[data-event]').forEach(el=>{el.onclick=()=>admin?editEvent(el.dataset.event):showDetails(el.dataset.event);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click()}}})}
function sectionSelect(c,value=''){return `<option value="">Select section</option><option value="none" ${value==='none'?'selected':''}>No sections</option>`+sectionOptions(c).map(n=>`<option value="${n}" ${n===value?'selected':''}>${n}</option>`).join('')}
function openSections(){$('sectionFields').innerHTML=activeCourses().map(c=>`<div class="section-field"><label><input type="checkbox" data-enable="${escape(c.id)}" ${prefs[c.id].enabled?'checked':''}><span><strong>${escape(c.id)}</strong><br><small>${escape(c.name)}</small></span></label><select data-section="${escape(c.id)}" aria-label="${escape(c.id)} section">${sectionSelect(c,prefs[c.id].section)}</select></div>`).join('')||'<p>No courses selected. Add courses with the + button.</p>';$('sectionsDialog').showModal()}
$('sectionsForm').onsubmit=e=>{e.preventDefault();document.querySelectorAll('[data-enable]').forEach(el=>prefs[el.dataset.enable].enabled=el.checked);document.querySelectorAll('[data-section]').forEach(el=>prefs[el.dataset.section].section=el.value);persist('prefs',prefs);$('sectionsDialog').close();render();toast('Schedule settings saved')};
function addCourse(id){manualRemoves=manualRemoves.filter(x=>x!==id);if(!manualAdds.includes(id))manualAdds.push(id);prefs[id].enabled=true;persistCourses();render();renderCatalog();toast('Course added to your schedule')}
function removeCourse(id){manualAdds=manualAdds.filter(x=>x!==id);if(!manualRemoves.includes(id))manualRemoves.push(id);persistCourses();render();if($('coursesDialog').open)renderCatalog();toast(id+' removed. Add it back with +.');}
function persistCourses(){persist('manualAdds',manualAdds);persist('manualRemoves',manualRemoves);persist('prefs',prefs)}
function renderCatalog(){const query=$('courseSearch').value.toLowerCase();const active=new Set(activeCourses().map(c=>c.id));const matches=courses.filter(c=>(c.id+' '+c.name).toLowerCase().includes(query));$('catalogResults').innerHTML=matches.map(c=>`<div class="catalog-row">${active.has(c.id)?`<input class="catalog-toggle" type="checkbox" data-catalog-toggle="${escape(c.id)}" aria-label="Show ${escape(c.id)}" ${prefs[c.id].enabled?'checked':''}>`:''}<div><strong style="color:${c.color}">${escape(c.id)}</strong><small>${escape(c.name)}</small><span class="catalog-term">${c.term==='AB'?'Full year':c.term==='A'?'Term A · Fall':'Term B · Winter'}</span></div><button class="button ${active.has(c.id)?'':'primary'}" data-catalog="${escape(c.id)}" data-selected="${active.has(c.id)}">${active.has(c.id)?'Remove':'Add'}</button></div>`).join('')||'<p>No matching courses. Add an unlisted course below.</p>';document.querySelectorAll('[data-catalog-toggle]').forEach(el=>el.onchange=()=>setCourseEnabled(el.dataset.catalogToggle,el.checked));document.querySelectorAll('[data-catalog]').forEach(b=>b.onclick=()=>b.dataset.selected==='true'?removeCourse(b.dataset.catalog):addCourse(b.dataset.catalog))}
function openCatalog(){$('courseSearch').value='';renderCatalog();$('coursesDialog').showModal()}
$('courseSearch').oninput=renderCatalog;
$('customCourseForm').onsubmit=e=>{e.preventDefault();const id=$('customCode').value.trim().toUpperCase().replace(/\s+/g,' '),name=$('customName').value.trim();if(!id||!name)return;if(courses.some(c=>c.id===id)){toast('That course is already in the catalogue.');return}const c={id,name,term:$('customTerm').value,sectionCount:Number($('customSections').value),color:'#b75d24',year:null};courses.push(c);customCourses.push(c);prefs[id]={enabled:true,section:c.sectionCount===0?'none':''};persist('customCourses',customCourses);$('customCourseForm').reset();addCourse(id)};
['aise','bme','ivey'].forEach(id=>$('route-'+id).onchange=()=>{selectedRoute=$('route-'+id).checked?id:'base';persist('route',selectedRoute);render();toast(routeCatalog[selectedRoute].label+' selected')});
$('resetRoute').onclick=()=>{manualAdds=[];manualRemoves=[];activeCourses().forEach(c=>prefs[c.id].enabled=!isWriting(c.id)||c.id===(selectedRoute==='aise'?'WRIT 2130G':'WRIT 2130F'));persistCourses();render();toast('Restored this route’s course list')};
function updateEventSections(value='all'){const c=course($('eventCourse').value);$('eventSection').innerHTML='<option value="all">'+(c.sectionCount===0?'Everyone · no sections':'All sections')+'</option>'+sectionOptions(c).map(n=>`<option value="${n}">${n}</option>`).join('');$('eventSection').value=sectionOptions(c).includes(value)?value:'all'}
$('eventCourse').onchange=()=>updateEventSections();
function editEvent(id){const e=events.find(e=>e.id===id);$('eventForm').reset();$('eventId').value=id||'';$('eventDialogTitle').textContent=e?'Edit event':'Add an event';$('eventCourse').innerHTML=courses.map(c=>`<option value="${escape(c.id)}">${escape(c.id)} · ${escape(c.name)}</option>`).join('');if(e){['Title','Course','Type','Date','Time','Section','Status','Notes','Source'].forEach(k=>$('event'+k).value=e[k.toLowerCase()]||'')}else $('eventDate').value=monthKey()+'-01';updateEventSections(e?.section||'all');$('deleteEvent').hidden=!e;$('eventDialog').showModal()}
$('eventForm').onsubmit=e=>{e.preventDefault();const item={id:$('eventId').value||crypto.randomUUID()};['Title','Course','Type','Date','Time','Section','Status','Notes','Source'].forEach(k=>item[k.toLowerCase()]=$('event'+k).value.trim());if(!item.title){$('eventTitle').focus();return}if(item.source&&!/^https?:\/\//i.test(item.source)){toast('Use an http or https source link.');return}item.updatedAt=new Date().toISOString();const idx=events.findIndex(e=>e.id===item.id);if(idx>=0)events[idx]=item;else events.push(item);persist('events',events);month=new Date(date(item.date).getFullYear(),date(item.date).getMonth(),1);$('eventDialog').close();render();toast('Event saved in this browser')};
$('deleteEvent').onclick=()=>{if(!confirm('Delete this sample event?'))return;events=events.filter(e=>e.id!==$('eventId').value);persist('events',events);$('eventDialog').close();render();toast('Event deleted')};
function showDetails(id){const e=events.find(e=>e.id===id),c=course(e.course);$('detailContent').innerHTML=`<div class="detail-info"><span class="badge ${escape(e.type)}">${escape(e.type)}</span><h2>${escape(e.title)}</h2><strong style="color:${c.color}">${escape(c.id)} · ${escape(c.name)}</strong><br>${fmt(e.date,{weekday:'long',month:'long',day:'numeric',year:'numeric'})}<br>${time(e.time)} · America/Toronto<br>${e.section==='all'?(c.sectionCount===0?'No sections':'All sections'):escape(e.section)} · ${escape(e.status)}<p class="detail-notes">${escape(e.notes)}</p>${e.source&&/^https?:\/\//i.test(e.source)?`<a class="detail-link" href="${escape(e.source)}" target="_blank" rel="noopener noreferrer">View official source ↗</a>`:''}<p class="fine">Sample information. Confirm dates with your official course announcements.</p></div>`;$('detailDialog').showModal()}
$('sectionButton').onclick=openSections;$('coursesNav').onclick=$('manageCourses').onclick=openCatalog;$('scheduleNav').onclick=()=>{admin=false;render()};$('adminNav').onclick=()=>{admin=true;render()};$('addEvent').onclick=()=>editEvent();$('listView').onclick=()=>{view='list';render()};$('calendarView').onclick=()=>{view='calendar';render()};$('previous').onclick=()=>{month.setMonth(month.getMonth()-1);render()};$('next').onclick=()=>{month.setMonth(month.getMonth()+1);render()};$('today').onclick=()=>{const d=date(nowKey);month=new Date(d.getFullYear(),d.getMonth(),1);render()};$('search').oninput=render;$('typeFilter').onchange=render;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=() =>$(b.dataset.close).close());render();
